import{_ as t,o,c as s,a2 as r}from"./chunks/framework.u0XqMXcb.js";const m=JSON.parse('{"title":"Trusted vs. Untrusted Models","description":"","frontmatter":{"title":"Trusted vs. Untrusted Models"},"headers":[],"relativePath":"docs/privacy-and-security/trusted-vs-untrusted-models.md","filePath":"docs/privacy-and-security/trusted-vs-untrusted-models.md","lastUpdated":1790281380000}'),a={name:"docs/privacy-and-security/trusted-vs-untrusted-models.md"};function d(n,e,u,l,i,c){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="trusted-vs-untrusted-models" tabindex="-1">Trusted vs. Untrusted Models <a class="header-anchor" href="#trusted-vs-untrusted-models" aria-label="Permalink to &quot;Trusted vs. Untrusted Models&quot;">​</a></h1><p>In Settings → Models, you configure a <strong>trusted</strong> main model — the one with access to your actual project data — separately from any <strong>untrusted</strong> supporting models used for other backend tasks. Chats always use the trusted model, and an untrusted model is never given access to your data.</p><h2 id="builtin-vs-configured" tabindex="-1">Builtin vs. configured <a class="header-anchor" href="#builtin-vs-configured" aria-label="Permalink to &quot;Builtin vs. configured&quot;">​</a></h2><p>OrbySystems&#39;s builtin models run entirely on your own machine, under OrbySystems&#39;s own control — because of that, they&#39;re always local and always trusted, with nothing to decide. A configured model is one that is hosted somewhere else. It could be hosted by local software like LM studio which you manage, or on another machine in your private network, or by a third party provider in the cloud (like OpenAI or OpenRouter).</p><h2 id="trusted-vs-untrusted" tabindex="-1">Trusted vs untrusted <a class="header-anchor" href="#trusted-vs-untrusted" aria-label="Permalink to &quot;Trusted vs untrusted&quot;">​</a></h2><p>Trusted models are models that you can trust with your personal information and data. By default, all builtin models are trusted, because they run locally and data sent to them never leaves the machine. For models you configure yourself, you must decide if the model is trusted or not. This primarily depends on the host. Another local model you&#39;re running on another machine in the network is trusted, because its fully under your control. A model running by a third party provider would generally be considered untrusted, since you do not have 100% control over what happens to your data once it leaves your machine.</p><h2 id="when-untrusted-model-are-used" tabindex="-1">When untrusted model are used <a class="header-anchor" href="#when-untrusted-model-are-used" aria-label="Permalink to &quot;When untrusted model are used&quot;">​</a></h2><p>Some tasks are beyond the capability of small local models. That is when it is recommended to use a much more powerful, but likely untrusted model. This is needed for:</p><ul><li>Transactions Extractor Builder <a href="./../tools/transactions-extractor-builder">doc</a></li><li>Statement Downloader Builder <a href="./../tools/statement-downloader-builder">doc</a></li></ul><p>In these cases the flows instruct you to remove your PII from any data before sending it to the untrusted model.</p><h2 id="configuring-models" tabindex="-1">Configuring models <a class="header-anchor" href="#configuring-models" aria-label="Permalink to &quot;Configuring models&quot;">​</a></h2><p>See <a href="/OrbySystems-Finance/docs/settings/models">Settings → Models</a> to configure your trusted and untrusted models, and <a href="/OrbySystems-Finance/docs/tools/model-test">Model Test</a> / <a href="/OrbySystems-Finance/docs/tools/model-eval-suite">Model Eval Suite</a> to check a model works well before relying on it.</p>',12)])])}const y=t(a,[["render",d]]);export{m as __pageData,y as default};
